import * as React from "react";
import { 
    Alert,
    Button, 
    Dialog, 
    DialogActions, 
    DialogContent, 
    DialogTitle,
    Typography, 
} from '@mui/material';
import { LoadingButton } from '@mui/lab';
import useAxios from 'axios-hooks';
import serverPath from '../../../services/serverPath';
import { useDispatch, useSelector } from 'react-redux';
import { useSession } from '../../../services/globalConfig';
import TextFieldController from '../../../components/TextFieldController';
import { close } from "../../../redux/apps/livingroom/invitationNav";
import { addContact } from "../../../redux/apps/livingroom/contacts";
import regExpBase from '../../../config/regExpBase';

const ContactSendingMode = props => {
    const contacts = useSelector(state => state.contacts.value);
    const [{socket},] = useSession();
    const dispatch = useDispatch();

    React.useEffect(() => {
        if(!contacts)
            socket?.emit('contacts');
        socket.on('contacts', data => {
            const { contacts } = data;
            dispatch(addContact(contacts));
        });
    }, [socket, contacts, dispatch]);
    
    return (
        <React.Fragment>
            <DialogContent>

            </DialogContent>
            <DialogActions>
                <LoadingButton
                    // loading={loading}
                >Envoyer l'invitation</LoadingButton>
                <Button>Annuler</Button>
            </DialogActions>
        </React.Fragment>
    )
}

const EmailSendingMode = props => {
    const value = React.useRef('');
    const [checking, setChecking] = React.useState(false);
    const token = useSelector(state => state.user.value.token);
    const [{loading, error, data}, refetch] = useAxios(URL, {
        manual: true,
    });
    const dispatch = useDispatch();

    const handleSendInvitation = () => {
       if(value.current) {  
            refetch({
                data: {
                    targetMail: value.current,
                    object: 'connexion'
                },
                method: 'post',
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            })
       } else {
        setChecking(true);
       }
    };

    return ( !data ? 
        (<React.Fragment>
            <DialogContent sx={{width: 400}}>
                <Typography variant="body2">
                    Pour entrer en relation avec un contact. 
                    veuillez lui soumetre une invitation par email
                </Typography>
                <TextFieldController
                    type="email"
                    ref={value}
                    checking={checking}
                    regExp={regExpBase.email}
                    size="small"
                    label="Email"
                    fullWidth
                    icon
                    margin="dense"
                />
                {!!error &&
                <Alert severity="error">
                    Impossible de soumetre votre invitation, 
                    une erreur est survenue lors de la demande
                </Alert>}
            </DialogContent>
            <DialogActions>
                <LoadingButton
                    loading={loading}
                    onClick={handleSendInvitation}
                    variant="contained"
                    size="small"
                >Envoyer l'invitation
                </LoadingButton>
                <Button 
                    size="small"
                    onClick={() => 
                        dispatch(close())
                    }
                >Annuler</Button>
            </DialogActions>
        </React.Fragment>) :
        <React.Fragment>
            <DialogContent sx={{width: 400}}>
                <Alert>
                    L'invitation a été soumise avec 
                    succèss. {value.current} sera notifié 
                    de votre demande
                </Alert>
            </DialogContent>
            <DialogActions>
                <Button
                    size="small"
                    onClick={() => 
                        dispatch(close())
                    }
                >ok</Button>
            </DialogActions>
        </React.Fragment>
    )
}

export default function NavInvite () {
    const nav = useSelector(state => state.invitationNav.value);
    return (
        <React.Fragment>
            <Dialog
                open={nav.open}
                BackdropProps={{
                    sx: {
                        backdropFilter: 'blur(15px)'
                    }
                }}
            >
                <DialogTitle>
                    Inviter un contact
                </DialogTitle>
                {nav.mode === 'email' && <EmailSendingMode />}
                {nav.mode === 'contact' && <ContactSendingMode />}
            </Dialog>
        </React.Fragment>
    );

}

const URL = serverPath('/api/chat/invite');
