import React from 'react';
import { 
    Box,
    Typography,
} from "@mui/material";
import { useSelector } from "react-redux";
import BooksContent from "./BooksContent";
import ImagesContent from "./ImagesContent";
import VideosContent from "./VideosContent";

export default function MedialibraryContent () {
    const subApp = useSelector(state => state.censorshipNavRight.value.subApp);
    const censorshipData = useSelector(state => state.censorshipData.value);
    const data = censorshipData[`medialibrary/${subApp}`];
    const del = 'api/stuff/frozen/';
    const val = 'api/stuff/';

    return (
        <Box
            sx={{display: 'flex', flex: 1}}
        >
            {data?.length === 0 ?
           (<Box
                sx={{
                    display: 'flex', 
                    flex: 1,
                    justifyContent: 'center',
                    alignItems: 'center',
                }}
           >
              <Typography variant='body2' color="text.secondary" align="center">Aucun élement trouvé</Typography>  
           </Box>) :
            (<React.Fragment>
                {subApp === 'books' &&  <BooksContent uris={{del, validate: `${val}bibliotheque`, frozenType: 'book' }} data={data}/>}
                {subApp === 'photos' &&  <ImagesContent uris={{del, validate: `${val}phototheque`, frozenType: 'image' }} data={data}/>}
                {subApp === 'films' &&  <VideosContent uris={{del, validate: `${val}filmotheque`, frozenType: 'film' }} data={data}/>}
            </React.Fragment>)}
        </Box>     
    );
}