import * as React from 'react';
import {
    Avatar,
    Box,
    List,
    Typography
} from '@mui/material';
import { ContactInfo } from './NavRightInfo';
import { useSelector } from 'react-redux';
import { Stack } from '@mui/system';
import ContactItem from '../../../component/ContactItem';
import Groups2RoundedIcon from '@mui/icons-material/Groups2Rounded';

export default function NavRightInfoContent () {
    const chat = React.useContext(ContactInfo);
    const userId = useSelector(state => state.user.value.id);

    const user = chat.type === 'room' ? chat : chat.members.find(
        ({_id:user}) => user._id !== userId
        ) ;

    const name = chat.type === 'room' ? user.name : `${user._id.lname} ${user._id.mname || ''} ${user._id.fname}`
    
    console.log(chat);

    return (
        <Box
            sx={{
                display: 'flex',
                flex: 1,
                flexDirection: 'column',
                overflow: 'auto',
            }}
        >
            <Box
                sx={{
                    bgcolor: 'background.paper',
                    mt: 1,
                    py: 1,
                }}
            >
                <Box
                    sx={{
                        display: 'flex',
                        justifyContent: 'center',
                        
                    }}
                >
                <Avatar
                    sx={{
                        width: 130,
                        height: 130,
                    }}
                    {...chat.type === 'room' ? {
                        children : <Groups2RoundedIcon
                        sx={{
                            fontSize: 90
                        }}
                    />
                    } : {}}
                />
                </Box>
                <Typography 
                    align="center"
                    sx={{
                        mt: 1,
                        fontWeight: 300,
                    }}
                    variant="h5"
                >
                    {name}
                </Typography>
                <Typography 
                    align="center"
                    sx={{mt: 1}}
                    color="text.secondary"
                >
                    {chat.description || user?._id.email} 
                </Typography>
            </Box>
            <Box
                sx={{
                    bgcolor: 'background.paper',
                    mt: 1,
                    py: 1,
                    px: 1
                }}
            >
                <Typography variant="h6" fontSize={15} color="text.secondary"> 
                    Medias et documents
                </Typography>
                <Stack
                    justifyContent="center"
                    alignItems="center"
                    display="flex"
                    height={130}
                > 
                    <Typography  align="center" variant="caption" color="text.secondary"> 
                        Aucun élement touvé
                    </Typography>
                </Stack> 
            </Box>
           {chat.type === 'direct' ?
            (<Box
                sx={{
                    bgcolor: 'background.paper',
                    mt: 1,
                    py: 1,
                    px: 1
                }}
            >
                <Typography variant="h6" fontSize={15} color="text.secondary"> 
                    Grade
                </Typography>
                <Typography variant="caption"> 
                    {user?._id?.grade?.grade}
                </Typography>  
                <Typography variant="h6" fontSize={15} color="text.secondary"> 
                    Role
                </Typography> 
                <Typography variant="caption"> 
                    {user?._id?.grade?.role}
                </Typography>  
            </Box>) :

            <List
              disablePadding  
              sx={{
                bgcolor: 'background.paper',
                mt: 1,
                flex: 1,
              }}
              subheader={
                <Typography 
                    sx={{
                        pl: 1, 
                        pt: 1,
                    }} 
                    variant="h6" fontSize={15} 
                    color="text.secondary"
                > 
                    Membres
                </Typography> 
              }
            >
                {chat?.members.map(({_id:user, role}, key) => 
                    <ContactItem
                        key={key}
                        disabledSecondaryAction
                        name={`${user.lname} ${user.mname || ''} ${user.fname}`}
                        message={role === 'admin' && 'Administrateur'}
                    />
                    )
                }
            </List>

            }
        </Box>
    )
}