import * as React from 'react';
import {
    Box,
} from '@mui/material';
import { useDispatch, useSelector } from 'react-redux';
import { closeInfo } from '../../../../../redux/apps/livingroom/infoContact';
import NavRightInfoHeader from './NavRightInfoHeader';
import NavRightInfoContent from './NavRightInfoContent';

export const ContactInfo = React.createContext(null);

export default function NavRightInfo () {
    const [open, setOpen] = React.useState(false);
    const dispatch = useDispatch();
    const contact = useSelector(state => state.infoContact.value);

    React.useEffect(() => {
      if(contact)
        setOpen(true);
    }, [contact, setOpen]);

    return (
      <React.Fragment>
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            width: open ? 360 : 0,
            transition: theme => theme.transitions.create('width', {
              easing: theme.transitions.easing.sharp,
              duration: theme.transitions.duration.leavingScreen,
            }),
            bgcolor: 'background.default'
          }}
          onTransitionEnd={() =>  {
              if(!open) dispatch(closeInfo());
          }}
        >
          { contact &&
          <ContactInfo.Provider value={contact}>
            <NavRightInfoHeader
              onClose={() => setOpen(false)}
            />
            <NavRightInfoContent />
          </ContactInfo.Provider>
          }
        </Box>
      </React.Fragment>
    );
}