import { createSlice } from "@reduxjs/toolkit";
import persistReducer from "redux-persist/es/persistReducer";
import session from "redux-persist/lib/storage/session";

const navRight = createSlice({
    name: 'medialibraryNavRight',
    initialState: {
        value: {
            tab: 'home',
            data: {
                books: null,
                images: null,
                films: null,
            },
            open: false,
            photoLibrary: {
                selectedImage: null,
            },
            bookLibrary: {
                bookTypes: null,
                selectedBookType: null,
            }
        }
    },

    reducers: {
        setData(state, actions) {
            state.value = {
                ...state.value,
                data: {
                    ...state.value.data,
                    ...actions.payload,
                },
            };
        },
        setTab(state, actions) {
            const { tab } = actions.payload;
            state.value = {
                ...state.value,
                tab,
            }
        },
        openApp(state) {
            state.value = {
                ...state.value,
                open: true
            }
        },
        viewImage(state, actions) {
            const { image:selectedImage } = actions.payload;
            state.value = {
                ...state.value,
                photoLibrary: {
                    ...state.value.photoLibrary,
                    selectedImage,
                } 
            }
        },
        setBookTypes(state, actions) {
            const { bookTypes } = actions.payload;
            state.value = {
                ...state.value,
                bookLibrary: {
                    ...state.value.bookLibrary,
                    bookTypes,
                } 
            }
        },
        selectedTypeBook(state, actions) {
            const { type } = actions.payload;
            state.value = {
                ...state.value,
                bookLibrary: {
                    ...state.value.bookLibrary,
                    selectedBookType: type,
                } 
            }
        },

    }
});

export const { 
    setTab, 
    setData, 
    openApp, 
    viewImage, 
    setBookTypes, 
    selectedTypeBook,
} = navRight.actions;

export default persistReducer({
    storage: session,
    key: 'medialibrary_geid_app'
}, navRight.reducer);