import { createSlice } from "@reduxjs/toolkit";

const infoContact = createSlice({
    name: 'infoContact',
    initialState: {
        value: null,
    },
    reducers: {
        closeInfo (state) {
            state.value = null;
        },
        viewInfos(state, action) {
            state.value =  action.payload;
        }
    }
});

export const { closeInfo, viewInfos } = infoContact.actions;
export default infoContact.reducer;