const handleViewMessage = (contact, userId) => {
  const lastMessage = [...contact.messages]?.find(
    (message, index, messages) => (messages.length - 1) === index );
  if(lastMessage) {
    
    const {type:mssType, sender, content } = lastMessage;
    const mss = mssType === 'text' ? content : '';
    return contact?.type === 'room' ? `${sender?.lname}: ${mss}` : mss;

  } else {

    const {_id: user} = contact.members?.find(({_id:user}) => user._id !== userId);
    return contact?.type === 'room' ? 
    `Nouveau salon ${contact.name} créé` : `Nouveau discussion avec ${user.lname}`;

  }
};

const handleViewTime = (contact, timestamp=false) => {
  const lastMessage = [...contact.messages]?.findLast(
    (message, index, messages) => (messages.length - 1) === index );
  
    const { createdAt } = lastMessage || contact;
    const time = new Date(createdAt);
    const current = new Date();
    const yesterday = new Date(current.getTime() - (86400 * 1000));
    //const week = new Date(current.getTime() - (86400 * 1000))

    if(timestamp)
      return time.getTime();

    if(time.getDate() === current.getDate())
      return `Aujourd'hui`
    else if(yesterday.getDate() === time.getDate())
      return `Hier`
    else return time.toLocaleDateString({ year: 'numeric', month: 'numeric', day: 'numeric' });
}

const sortMessages = contacts => { 
  return [...contacts || []].sort((a, b) => handleViewTime(a, true) - handleViewTime(b, true))
  .reverse();

  
}

const getFullName = (contact, userId) => {
  const {_id: user} = contact.members?.find(({_id:user}) => user._id !== userId);
  return `${user.lname} ${user.mname || ''} ${user.fname}`;
};

const ButtonOption = props => {
    const [values, setValues] = React.useState({
      anchorEl: null,
      options: [],
    });
    const open = Boolean(values.anchorEl);
  
    const handleClick = (event, options) => {
      setValues({
        anchorEl: event.currentTarget,
        options,
      });
    };
  
    return (
      <React.Fragment>
        <Stack
          spacing={1}
          direction="row"
          sx={{ px: 1, my: 1 }}
        >
          <CustomButton
            children="Nouveau salon"
            variant="outlined"
            size="small"
            endIcon={<ExpandMoreRoundedIcon />}
            startIcon={
              <ImgToIcon
                src={groupImage}
                size={25}
              />
            }
            color="inherit"
            onClick={event => {
              handleClick(event, roomsOptionsNav)
            }}
          />
          <CustomButton
            children="Discussion"
            variant="outlined"
            size="small"
            color="inherit"
            endIcon={<ExpandMoreRoundedIcon />}
            startIcon={
              <ImgToIcon
                src={chatImage}
                size={25}
              />
            }
            onClick={event => {
              handleClick(event, talkingOptionsNav)
            }}
          />
        </Stack>
        <MenuOptions
          anchorEl={values.anchorEl}
          open={open}
          onClose={() => setValues({
            ...values,
            anchorEl: null,
          })}
          anchorOrigin={{
            vertical: 'bottom',
            horizontal: 'left',
          }}
          transformOrigin={{
            vertical: 'top',
            horizontal: 'left',
          }}
          options={values.options}
        />
      </React.Fragment>
    )
};

const ContactItemWrapper = ({contact, index, contacts}) => {
  const userId = useSelector(state => state.user.value.id);
  const dispatch = useDispatch();
  const contactId = useSelector(state => state.chats.value?._id);
  const [open, setOpen] = React.useState(false);
  const anchorElRef = React.useRef();

  const options = [
    {
      label: `info du ${ contact.type === 'room' ? 'groupe' : 'contact'}`,
      icon: InfoRoundedIcon,
      action () {
        dispatch(viewInfos(contact));
      }
    }
  ];

  return (
    <React.Fragment>
      <ContactItem
          name={contact.type === 'room' ? contact.name : getFullName(contact, userId)}
          date={handleViewTime(contact)}
          selected={ contactId === contact._id}
          avatarProps={{
            ...contact.type === 'room' ? {
              children:  <Groups2RoundedIcon/>,
            } : {
              children:  (() => {
                const {_id: user} = contact.members?.find(({_id:user}) => user._id !== userId);
                return `${user.lname.charAt(0) + user.fname.charAt(0)}`;
              })(),
            },
            sx:{ fontSize: 15}
          }}
          onClick={() => {
            dispatch(startChat(contact));
          }}
          message={handleViewMessage(contact, userId)}
          divider={(contacts.length - 1) !== index}
          secondaryAction={{
            onClick() {
              setOpen(true);
            },
            ref: anchorElRef,
          }}
      />
       <MenuOptions
          open={open}
          onClose={() => setOpen(false)}
          anchorEl={anchorElRef.current}
          options={options}
       />
    </React.Fragment>
  )

};

const ListContacts = props => {
    
    const contacts = useSelector(state => state.talkingContacts.value);
    const [{socket},] = useSession();
    const dispatch = useDispatch();

    React.useEffect(() => {
        if(!contacts)
            socket?.emit('direct-chat');
        socket.on('chats', data => {
            const { chats } = data;
            dispatch(addContact(chats));
        });
        socket.on('direct-chat', () => {
          socket?.emit('direct-chat');
        });
    }, [socket, contacts, dispatch]);

   
    return (
        <Box
          sx={{
            display: 'flex',
            flex: 1,
            width: '100%',
            overflow: 'auto',
            flexDirection: 'column',
          }}
        >
          <LoadingList
              loading={!contacts}
              nbrList={3}
              
          />
                {!!contacts?.length &&
                <List
                 component={BoxScrollShadow}
                >
                    {sortMessages(contacts)?.map((contact, index, contacts) => (
                        <ContactItemWrapper
                          contact={contact}
                          key={contact._id}
                          index={index}
                          contacts={contacts}
                        />
                    ))}
                </List>
                }
              {contacts?.length === 0 && 
                <Stack
                    display="flex"
                    flex={1}
                    justifyContent="center"
                    alignItems="center"
                >
                    <Typography 
                        component="div" 
                        variant="body2" 
                        aling="center"
                        color="text.secondary"
                    >
                        Aucune discussion
                    </Typography>
                </Stack> 
                }
        </Box>
    );
};

export default function TalkinList () {
    return (
        <Box 
          sx={{
            width: '100%', 
            display: 'flex', 
            flex: 1, 
            flexDirection: 'column', 
            height: '100%',
          }}
        >
            <ButtonOption/>
            <ListContacts/>
        </Box>
    )
};