import { createSlice } from "@reduxjs/toolkit";

const navRight = createSlice({
    name: 'archivesNavRight',
    initialState: {
        value: {
            tab: 'docs',
            data: null,
            open: false,
            role: null,
            type: null,
            docTypes: null,
            loading: false,
        }
    },

    reducers: {
        setData(state, actions) {
            state.value = {
                ...state.value,
                data: actions.payload,
            };
        },
        getDocTypes(state, actions) {
            state.value = {
                ...state.value,
                docTypes: actions.payload,
            };
        },
        setTab(state, actions) {
            state.value = {
                ...state.value,
                tab: actions.payload,
            }
        },
        openApp(state) {
            state.value = {
                ...state.value,
                open: true
            }
        },
        setRole(state, actions) {
            state.value = {
                ...state.value,
                role: actions.payload,
            }
        },
        setType(state, actions) {
            state.value = {
                ...state.value,
                type: actions.payload,
            }
        },
        setLoad(state, actions) {
            state.value = {
                ...state.value,
                loading: actions.payload,
            }
        }
    }
});

export const { 
    setTab, 
    setData, 
    openApp, 
    setRole,
    setType,
    getDocTypes,
    setLoad,
} = navRight.actions;

export default navRight.reducer