import { createSlice } from "@reduxjs/toolkit";

const navLeft = createSlice({
    name: 'medialibraryNavLeft',
    initialState: {
        value: {
            open: true,
        }
    },
    reducers: {
        openNav (state) {
            state.value = {
                ...state.value,
                open: true,
            }
        },
        closeNav (state) {
            state.value = {
                ...state.value,
                open: false,
            }
        }
    }
});

export const { openNav, closeNav } = navLeft.actions;
export default navLeft.reducer;