import { createSlice } from "@reduxjs/toolkit";

const currentNavLeft = createSlice({
    name: 'currentNavLeft',
    initialState: {
        value: {
            value: 'chats',
            news: 0,
        }
    },
    reducers: {
        changeValue (state, action) {
            state.value = {
                ...state.value,
                value: action.payload,
            };
        }
    }
});

export const { changeValue } = currentNavLeft.actions;
export default  currentNavLeft.reducer;