import { 
    Box,
    Divider,
} from "@mui/material";
import { useSelector } from "react-redux";
import NavRightInfo from "./info/NavRightInfo";
import NavRightContent from "./content/NavRightContent";
import NavRightFooter from "./footer/NavRightFooter";
import NavRightHeader from "./header/NavRightHeader";
import { FrameBox } from "../../index.js";

export default function Chats ({
    localMessages,
    setLocalMessages}) {
    const contact =  useSelector(state => state.chats.value);
    const talks = useSelector(state => state.talkingContacts.value);
    const userId = useSelector(state => state.user.value.id);

    const user = contact?.type === 'room' ? contact :
    contact?.members?.find(({_id:user}, index, members) => 
    members.length === 1 ? true  : user._id !== userId)?._id || contact;

    const users = talks.filter(talk => talk.type === 'direct')
    .find(({members}) => members.find(
        ({_id:currentUser}) => currentUser._id === user._id
    ));

    const { messages } = (contact?.messages ? contact : users) || {};
    
    return (
        <FrameBox
            direction="row"
            divider={<Divider orientation="vertical" />}
        >
            <Box
                sx={{
                    display: 'flex',
                    flex: 1,
                    position: 'relative',
                    flexDirection: 'column',
                }}
            >
                <NavRightHeader user={user}/>
                <NavRightContent
                    messages={messages}
                    sender={user}
                    localMessages={
                        localMessages.filter(({userId}) => userId === user._id)
                    }
                    setLocalMessages={setLocalMessages}
                />
                <NavRightFooter
                    sender={user}
                    localMessages={localMessages}
                    setLocalMessages={setLocalMessages}
                />
            </Box>
            <NavRightInfo/>
        </FrameBox>
    );
}