import * as React from "react";
import {
    List,
    Box,
    Stack,
    Typography,
    ListSubheader,
} from '@mui/material';
import { useDispatch, useSelector } from "react-redux";
import LoadingList from "../../component/LoadingList";
import { useSession } from '../../../../services/globalConfig';
import { addContact } from "../../../../redux/apps/livingroom/contacts";
import ContactItem from "../../component/ContactItem";
import CustomButton from "../../component/CustomButton";
//import PersonAddRoundedIcon from '@mui/icons-material/PersonAddRounded';
import { open } from "../../../../redux/apps/livingroom/invitationNav";
import { startChat } from "../../../../redux/apps/livingroom/chats";
import addUserImage from '../../../../icons/icons8-ajouter-un-utilisateur-homme-64.png';
import ImgToIcon from '../../../../icons/ImgToIcon';

const sortContacts = contacts => {
    const alpha = 'ABCDEFGHIJKLMNOPARS';
    const contactsObject = {};
    alpha.toLocaleLowerCase().split('').forEach(char => {
        contactsObject[char] = contacts?.filter(
            contact => contact.lname?.charAt(0).toLocaleLowerCase() === char
            )
    })
    return Object.keys(contactsObject).map(label => contactsObject[label].length ? ({
        label: label.toLocaleUpperCase(),
        contacts: contactsObject[label],
    })  : null).filter(data => !!data);
};

export default function ContactsList () {
    const contacts = useSelector(state => state.contacts.value);
    const [{socket},] = useSession();
    const dispatch = useDispatch();

    React.useEffect(() => {
        if(!contacts)
            socket?.emit('contacts');
        socket.on('contacts', data => {
            const { contacts } = data;
            dispatch(addContact(contacts));
        });
    }, [socket, contacts, dispatch]);

    return (
        <Box
            sx={{
                width: '100%', 
                display: 'flex', 
                flex: 1, 
                flexDirection: 'column', 
                height: '100%',
            }}
        >
            <Box 
                sx={{
                    my:1, 
                    alignItems: 'center', 
                    display: 'flex', 
                    justifyContent: 'center',
                    mx: '25%'
                }}
            >
                <CustomButton
                    children="Inviter un contact"
                    variant="outlined"
                    startIcon={
                        <ImgToIcon
                            src={addUserImage}
                            size={25}
                        />
                    }
                    color="inherit"
                    onClick={() => 
                        dispatch(open({
                            mode: 'email',
                            data: {},
                            type: 'direct',
                        }))
                    }
                />
            </Box>
            <LoadingList
                loading={!contacts}
                nbrList={3}
            />
            {!!contacts?.length &&
                <List
                    disablePadding
                    sx={{
                        mx: 0,
                        px: 0,
                        width: '100%',
                        overflow: 'auto',
                        '& ul': {
                            mx: 0,
                            px: 0,
                        }
                    }}
                >
                    {sortContacts(contacts).map((data, index) => (
                        <li key={index}>
                            <ul>
                                <ListSubheader>{`${data.label}`}</ListSubheader>
                                {data.contacts.map((contact, index) => (
                                <ContactItem
                                    name={`${contact.lname} ${contact.mname || ''} ${contact.fname}`}
                                    key={contact._id}
                                    onClick={() => dispatch(startChat(contact))}
                                    avatarProps={{
                                        children:`${contact.lname.charAt(0) + contact.fname.charAt(0)}`,
                                        sx:{ fontSize: 15}
                                    }}
                                />
                                ))}
                            </ul>
                        </li>
                    ))}


                    {/* {contacts?.map(contact => (
                        <ContactItem
                            name={`${contact.lname} ${contact.mname} ${contact.fname}`}
                            key={contact._id}
                            onClick={() => dispatch(startChat(contact))}
                        />
                    ))} */}
                </List>
            }
            {contacts?.length === 0 &&
            <Stack
                display="flex"
                flex={1}
                width="100%"
                height="100%"
                justifyContent="center"
                alignItems="center"
            >
                <Typography 
                    component="div" 
                    color="text.secondary" 
                    variant="body2"
                    aling="center"
                >
                    Aucun contact trouvé
                </Typography>
            </Stack>
            }
        </Box>
    );
}