import {
    CardMedia,
    Stack,
    Toolbar,
    Box,
    Typography,
    IconButton,
} from '@mui/material';
import fileExtensionBase from '../../../../../config/fileExtensionBase';
import getFileExtension from '../../../../../utils/getFileExtension';
import WrapperSide from '../../../component/WrapperSide';
import VoiceToSendIcon from './VoiceToSendIcon';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import generateId from '../../../../../utils/generateId';

export default function SendFile ({
    values, 
    setValues,
    localMessages,
    setLocalMessages,
    sender
}) {

    const handleSendFile = () => {

        const { file } = values;
        setLocalMessages([
            ...localMessages,
            {
                _id: generateId(),
                userId: sender._id,
                file,
                createdAt: new Date(),
                started: false,
                type: sender.type ? sender.type : 'direct',
            }
        ]);
    
        setValues({
            ...values, 
            type: 'text',
            file: null,
        });
    };

    const handleClose = () => {
        setValues({
            ...values, 
            type: 'text',
            file: null,
        });
    }

    const info = fileExtensionBase.find(file => 
        ~file.exts.indexOf(
            getFileExtension(values.file?.name)
            )
        );

    return (
            <Stack 
                spacing={1}
                flex={1}
                justifyContent="center"
                alignItems="center"
                position="relative"
            >
            <Box>
                <IconButton
                    sx={{
                        position: 'absolute',
                        top: 10,
                        right: 5,
                    }}
                    onClick={handleClose}
                >
                    <CloseRoundedIcon/>
                </IconButton>
            </Box>
            
            <Typography variant="body2" sx={{my: 1}}>
                {values.file?.name}
            </Typography>    
             <Box>   
                <CardMedia
                    component={
                        info.type === 'image' ? 'img' : 
                        info.type === 'document' ? 'iframe' : info.type
                    }
                    src={URL.createObjectURL(values.file)}
                    sx={{height:430}}
                /> 
              </Box>
              <Toolbar>
                <WrapperSide>
                    <VoiceToSendIcon
                        variant="text"
                        onSendText={handleSendFile}
                    />   
                </WrapperSide>
              </Toolbar>     
            </Stack>
    )
}