import { createSlice } from "@reduxjs/toolkit";

const chats = createSlice({
    name: 'chats',
    initialState: {
        value: null,
    },
    reducers: {
        startChat (state, action) {
            state.value = action.payload;
        },
        closeChat (state) {
            state.value = null;
        }
    }
});

export const {  startChat, closeChat } = chats.actions;
export default  chats.reducer;