import React, { useLayoutEffect, useEffect } from 'react';
import { ThemeProvider} from '@mui/material';
import {
  ConfigProvider,
  SessionProvider,
  CookieProvider,
  useCookieParam,
  useSessionParam,
  useConfigParam,
} from './services/globalConfig';
import Auth from './routers/Auth';
import { useSelector } from 'react-redux';
import useSystemTheme from './utils/useSytemTheme';

export default function App() {
    const [config, configActions] = useConfigParam();
    const [session, sessionActions] = useSessionParam();
    const [cookie, cookieActions] = useCookieParam();
    const mode = useSelector(state => state.theme.value);

    const theme = useSystemTheme(mode);

    useLayoutEffect(() => {
      document.body.style.backgroundColor = theme.palette.background.default;
      document.body.style.height = '100vh';
    },[theme.palette.background.default]);


    return (
      <ThemeProvider {...{theme}}>
        <ConfigProvider value={[config, configActions]}>
          <SessionProvider value={[session, sessionActions]}>
            <CookieProvider value={[cookie, cookieActions]}>
              <Auth/>
            </CookieProvider>
          </SessionProvider>
        </ConfigProvider>
      </ThemeProvider>
    );
}
