import { Box, CardMedia, Grid, ImageListItemBar, Typography } from "@mui/material";
import React from "react";
import FileWrapper from "../../components/FileWrapper";
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import { useSelector } from "react-redux";

const VideoItem = ({file, uris}) => {
    const { fileUrl:src, sendedAt, title} = file;
    const date = (new Date(sendedAt)).toLocaleDateString('fr', {
        weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
    });

    return (
        <FileWrapper file={file} uris={uris}>
            <Box>
                <Box
                    sx={{
                        position: 'relative',
                        justifyContent: 'center',
                        alignItems: 'center',
                    }}
                >
                    <CardMedia
                        component="video"
                        src={src}
                    />
                    <Box
                        sx={{
                            position: 'absolute',
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                            top: 0,
                            height: '100%',
                            width: '100%'
                        }}
                    >
                        <PlayArrowRoundedIcon
                            fontSize="large"
                            sx={{color: 'white'}}
                        />
                    </Box>
                </Box>
                
                <ImageListItemBar
                    title={title}
                    position="below"
                    subtitle={date}
                />
            </Box>
        </FileWrapper>
    )
};

export default function VideosContent ({data, uris}) {
    const isSmall = useSelector(state => state.censorshipNavLeft.value.open);
    return (
        <Box
            sx={{display: 'flex', flex: 1}}
        >
            <Box component={Grid} container sx={{my: 1}}>
                {
                    data?.map((video, index, videos) => (
                        <Grid 
                            sx={{px:1}} 
                            item 
                            key={index} 
                            xs={isSmall ? 3 : 12/5}
                        >
                            <VideoItem
                                file={video}
                                uris={uris}
                            />
                        </Grid>
                    ))
                }
            </Box>
        </Box>
    );
}