import * as  React from "react";
import { 
    Avatar, 
    Divider, 
    IconButton, 
    ListItem, 
    ListItemAvatar, 
    ListItemIcon, 
    ListItemText,
    Zoom,
} from "@mui/material";
import { Stack } from "@mui/system";
import { LoadingButton } from '@mui/lab';
import InfoRoundedIcon from '@mui/icons-material/InfoRounded';

export default function ContactInvitationItem({
    loadingRefuse,
    loadingAccept,
    message,
    propsAvatar,
    onAccept,
    onRefuse,
    divider,
}) {
    const [showInfo, setShowInfo] = React.useState(false);

    return (
        <React.Fragment>
            <ListItem
                onMouseEnter={() => setShowInfo(true)}
                onMouseLeave={() => setShowInfo(false)}
            >
                <ListItemAvatar>
                    <Avatar
                        {...propsAvatar}
                    />
                </ListItemAvatar>
                    <ListItemText
                        primary={message || 'message'}
                        secondary={
                            <Stack
                                display="flex"
                                flex={1}
                                spacing={1}
                                direction="row"
                            >
                                <LoadingButton
                                    variant="contained"
                                    loading={loadingAccept}
                                    onClick={onAccept}
                                    size="small"
                                >Accepter
                                </LoadingButton>
                                <LoadingButton
                                    loading={loadingRefuse}
                                    onClick={onRefuse}
                                    size="small"
                                >Refuser
                                </LoadingButton>
                            </Stack>
                        }
                        secondaryTypographyProps={{
                            component: 'div'
                        }}
                    />
                    <Zoom in={showInfo}>
                        <IconButton size="small">
                            <InfoRoundedIcon fontSize="small" />
                        </IconButton>
                    </Zoom>
            </ListItem>
            {divider && <Divider variant="inset" component="li" />}
        </React.Fragment>
    );
}