import { createTheme } from "@mui/material";
import { useLayoutEffect, useState } from "react";
import  config from '../config/app.json';
export default function useSystemTheme(themeMode) {
    const darkThemeMediaquery = window.matchMedia(`(prefers-color-scheme: dark)`);
    const [theme, setTheme] = useState(darkThemeMediaquery.matches ? 'dark': 'light');

    useLayoutEffect(()=> {
        const handleChange = event => setTheme(event.target.matches ? 'dark': 'light');
        darkThemeMediaquery
        .addEventListener('change', handleChange);
        return () => darkThemeMediaquery
        .removeEventListener('change', handleChange);
    },[theme]);

    const mode = (themeMode ? (themeMode === 'system' ? theme: themeMode) : theme);
   
    return createTheme({
        palette: {
            mode,
            primary: {
                main: config.theme.primaryColor
            },
            background: {
                default: mode === 'dark' ? '#00173e' : '#eeeeee',
                paper: mode === 'dark' ? '#09162a' : '#ffffff',
            }
        }
})
    
    
}
