import * as React from 'react';
import {
    AppBar, 
    Toolbar, 
    Typography,
    IconButton
} from '@mui/material';
import { ContactInfo } from './NavRightInfo';
import ArrowForwardIosRoundedIcon from '@mui/icons-material/ArrowForwardIosRounded';

export default function NavRightInfoHeader ({onClose}) {
    const chat = React.useContext(ContactInfo);

    return (
        <React.Fragment>
          <AppBar 
            position="static" 
            color="default"
            sx={{
                boxShadow: 0,
            }}
        >
            <Toolbar>
                <IconButton 
                    size="small" 
                    sx={{mr: 2}}
                    onClick={onClose}
                >
                    <ArrowForwardIosRoundedIcon fontSize="small"/>
                </IconButton>
                <Typography>
                    Infos du {chat.type === 'room' ? 'groupe' : 'contact'}
                </Typography>
            </Toolbar>
          </AppBar>
        </React.Fragment>
    )
}