import { configureStore } from "@reduxjs/toolkit";
import {
    FLUSH,
    REHYDRATE,
    PAUSE,
    PERSIST,
    PURGE,
    REGISTER,
  } from 'redux-persist';
import persistStore from "redux-persist/es/persistStore";
import theme from "./theme";
import user from "./user";
import screen from "./screen";
import currentNavLeft from "./apps/livingroom/currentNavLeft";
import contacts from "./apps/livingroom/contacts";
import talkingContacts from "./apps/livingroom/talkingContacts";
import fastContactNav from "./apps/livingroom/fastContactNav";
import invitationNav from "./apps/livingroom/invitationNav";
import notifications from "./apps/livingroom/notifications";
import chats from "./apps/livingroom/chats";
import infoContact from "./apps/livingroom/infoContact";
import censorshipNavLeft from "./apps/censorship/censorshipNavLeft";
import censorshipNavRight from "./apps/censorship/censorshipNavRight";
import censorshipData from "./apps/censorship/censorshipData";
import medialibraryNavLeft from "./apps/medialibrary/medialibraryNavLeft";
import medialibraryNavRight from "./apps/medialibrary/medialibraryNavRight";
import archivesNavLeft from "./apps/archives/archivesNavLeft";
import archivesNavRight from "./apps/archives/archivesNavRight";
import newUser from './newUser';

const store = configureStore({
    reducer: {
        user,
        theme,
        screen,
        newUser,
/////////// livingroom reducers ///////////
        currentNavLeft,
        contacts,
        talkingContacts,
        fastContactNav,
        invitationNav,
        notifications,
        chats,
        infoContact,
/////////// censorship reducers ///////////
        censorshipNavLeft,
        censorshipNavRight,
        censorshipData,
/////////// censorship medialibrary ///////
        medialibraryNavLeft,
        medialibraryNavRight,
/////////// censorship archives ///////////
        archivesNavLeft,
        archivesNavRight,
///////////////////////////////////////////
    },
    middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: [FLUSH, REHYDRATE, PAUSE, PERSIST, PURGE, REGISTER],
      },
    }),
});

const persistor = persistStore(store);
export { store, persistor };