import { createSlice } from "@reduxjs/toolkit";

const navLeft = createSlice({
    name: 'archivesNavLeft',
    initialState: {
        value: {
            open: true,
            trees: {},
        }
    },
    reducers: {
        openNav (state) {
            state.value = {
                ...state.value,
                open: true,
            }
        },
        closeNav (state) {
            state.value = {
                ...state.value,
                open: false,
            }
        },
        addTree(state, actions) {
            state.value = {
                ...state.value,
               trees: {
                ...state.value.trees,
                ...actions.payload,
               }
            }
        }
    }
});

export const { openNav, closeNav, addTree } = navLeft.actions;
export default navLeft.reducer;