import { createSlice } from "@reduxjs/toolkit";

const navRight = createSlice({
    name: 'censorshipNavRight',
    initialState: {
        value: {
            app: null,
            subApp: null,
        }
    },
    reducers: {
        setApp (state, actions) {
            const { label:app, app:subApp } = actions.payload.app;
            state.value = {
                ...state.value,
                app, 
                subApp,
            }
        },
        setSubApp (state, actions) {
            const { app:subApp } = actions.payload.app;
            state.value = {
                ...state.value,
                subApp,
            }
        },
    }
});

export const { setApp, setSubApp } = navRight.actions;
export default navRight.reducer;