import { createSlice } from "@reduxjs/toolkit";

const notifications = createSlice({
    name: 'notifications',
    initialState: {
        value: {
            invitations: [],
            nbr: 0,
        }
    },
    reducers: {
        addNotification (state, action) {
            state.value = {
                ...state.value,
                ...action.payload,
            }
        }
    }
});

export const { addNotification } = notifications.actions;

export default  notifications.reducer;