import * as React from 'react';
import {
    Box
} from '@mui/material';
import BoxScrollShadow from '../../livingroom/component/BoxScrollShadow';
import { useSelector } from 'react-redux';
import CensorshipLeftHeader from './header/CensorshipLeftHeader';
import CensorshipNavLeftContent from './content/CensorshipNavLeftContent';

export default function CensorshipNavLeft () {
    const [open, setOpen] = React.useState(false);
    const openNav = useSelector(state => state.censorshipNavLeft.value.open);
   
    React.useEffect(() => {
      if(openNav)
        setOpen(true);
    }, [openNav, setOpen]);

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                width: openNav ? 360 : 0,
                transition: theme => theme.transitions.create('width', {
                    easing: theme.transitions.easing.sharp,
                    duration: theme.transitions.duration.leavingScreen,
                }),
                overflow: 'hidden',
                bgcolor: 'background.paper',
            }}
            onTransitionEnd={() => {
                if(!openNav)
                    setOpen(false);
            }}
        >
            { open &&
                <Box
                    sx={{
                        transition: theme => theme.transitions.create('left', {
                            easing: theme.transitions.easing.sharp,
                            duration: theme.transitions.duration.leavingScreen,
                        }),
                        position: 'relative',
                        left: - openNav ?  0 : -360,
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'column',
                    }}
                >
                    <CensorshipLeftHeader/>
                    <CensorshipNavLeftContent/>
                </Box>
            }
        </Box>
    )
}