import { 
    Box, 
    Typography, 
    Divider,
    Stack,
    List,
    ListItem,
    ListItemButton,
    ListItemText,
    ListItemIcon, 
} from '@mui/material';
import GeidLogo from './GeidLogo';
import useSize from '../services/useSize';
import DoubleArrowIcon from '@mui/icons-material/DoubleArrow';
import { useSelector } from 'react-redux';
import React from 'react';

export default function HeaderLink () {
    const size = useSize();
    const screen = useSelector(state => state.screen.value);
    const isSmallScreen = ['xs', 'md'].find( key  => size.key === key);

    const link = document.createElement('a');
    link.href = '/home';

    return ( screen === 'normal' &&
        <Box sx={{bgcolor: 'primary.main'}}>
            <Stack 
                padding={1}
                direction="row"
                sx={{
                    justifyContent: 'center',
                    alignItems: 'center',
                    display: 'flex',
                }}
            >
                <Box sx={{flexGrow: isSmallScreen ? 1: 0}}>
                    <Box
                        component="img"
                        src={require('../assets/logo_ministere_budget.webp')}
                        sx={{height: '100px'}}
                    />
                </Box>
                <Box sx={{flexGrow: isSmallScreen ? 0: 1}}>
                    <GeidLogo 
                        sx={{color: 'white', cursor: 'pointer', display: 'inline-block',}}
                        onClick={() => {
                            link.click();
                        }}
                    />
                    {!isSmallScreen && 
                    <React.Fragment>
                        <Divider sx={{maxWidth: 300}} />
                        <Typography 
                            fontSize={15} 
                            color="white"
                        >Gestion Electronique de l'Information et des Documents</Typography>
                    </React.Fragment>
                    }
                </Box>

                { !isSmallScreen &&
                <Box>
                    <List
                        sx={{ color : 'white' }}
                        aria-label="links"
                    >{[{
                        href: 'https://budget.gouv.cd/',
                        title: 'Ministere du budget',
                    }, {
                        href: '',
                        title: 'Secretariat general',
                    }].map((link, index) => (
                        <ListItem disablePadding key={index}>
                            <ListItemButton
                                sx={{height: 30}}
                                LinkComponent="a"
                                target="_blank"
                                href={link.href}
                            >
                                <ListItemIcon>
                                    <DoubleArrowIcon sx={{color : 'white'}} />
                                </ListItemIcon>
                                <ListItemText 
                                    primary={link.title}
                                    primaryTypographyProps={{
                                        fontSize: 15,
                                        fontWeight: 'medium'
                                    }}
                                />
                            </ListItemButton>
                        </ListItem>
                    ))}
                    </List>
                </Box>}
            </Stack>
        </Box>
    )
}