import { createSlice } from "@reduxjs/toolkit";
import { store } from './';

const screen = createSlice({
    name: 'screen',
    initialState: {
        value: 'croped' || 'normal' || 'full',
    },
    reducers: {
        switchScreen (state, action) {
            state.value = action.payload || 'normal';
            if(action.payload === 'full')
               document.body.requestFullscreen();
            else 
                if(document.fullscreenElement)
                    document.exitFullscreen();
        }
    }
});

export const { switchScreen } = screen.actions;

document.body.addEventListener('fullscreenchange', () => {
    if(!document.fullscreenElement) 
        store.dispatch(switchScreen('normal'));
});
export default  screen.reducer;