import CryptoJS from "crypto-js";
const Utf8Encoded = CryptoJS.enc.Utf8;
const SECRET_SIGN = ``;
export const keyWord = ``;
export const encrypt = text => typeof text === 'string' ? CryptoJS.AES.encrypt(text, SECRET_SIGN)?.toString() : null;
export const decrypt = code => typeof code === 'string' ? CryptoJS.AES.decrypt(code?.toString(), SECRET_SIGN)?.toString(Utf8Encoded) : null;