import React, { useEffect } from 'react';
import {
    BrowserRouter,
    Routes as Switch,
    Route,
    Navigate,
} from 'react-router-dom';
import routes, { routeDisp } from './routes';
import Footer from '../components/Footer';
import HeaderLink from '../components/HeaderTitle';
import NotFound from '../views/NotFoud';
import SettingsNav from '../components/SettingsNav';
// import { useSession } from '../services/globalConfig';
// import Admin from '../private/Admin';
// import AdminLogin from '../private/AdminLogin';
import { useSelector } from 'react-redux';
import { useSession } from '../services/globalConfig';

export default function Auth () {
    const isAuth = useSelector(state => state.user.value.isAuthenticated);
    const newUser = useSelector(state => state.newUser);
    const oldUser = useSelector(state => state.user.value);
    const [,{setSession}] = useSession();

    useEffect(() => {
        if(newUser?.connected && !oldUser?.isAuthenticated) {
          setSession('user', {
            token: newUser?.token,
            email: newUser?.email,
            firstName: newUser?.firstname,
            lastName: newUser?.lastaname,
            middleName: newUser?.middlename,
            tel: newUser?.number,
            permission: newUser?.permissions,
            imageUrl: newUser?.image,
            id: newUser?.id,
            isAuthenticated: true,
            level: {
                grade: newUser?.grade,
                role: newUser?.role,
            },
        });
        }
      }, [newUser?.connected, oldUser?.isAuthenticated]);

      //console.log(newUser, oldUser);

    return ( //(newUser?.connected && oldUser?.isAuthenticated) &&
        <React.Fragment>
            <SettingsNav/>
            <HeaderLink/>
                <BrowserRouter>
                    <Switch>
                    {routes.map((route, index) => {
                        const accessMode = isAuth ? 'private' : 'public';
                        return RegExp(route.accessMode).test(accessMode) && (
                            <React.Fragment key={index}>{routeDisp(route)}</React.Fragment>
                        );
                    })}
                        {/* <Route
                            path='/admin'
                            element={!!getSession('admin') ?
                            <Admin/> : <AdminLogin/>}
                        /> */}
                        <Route path='*' element={<NotFound/>}/>
                        {/* <Route exact path='/' element={<Navigate to="/home"/>}/> */}
                    </Switch>
                </BrowserRouter>
            <Footer/>
        </React.Fragment>
    )
}

