import { Box, Grid } from "@mui/material";
import FileWrapper from "../../components/FileWrapper";
import BookPlan from '../../../../components/BookPlan';
import { useSelector } from "react-redux";

const BookItem = ({file, uris}) => {
    const { fileUrl:src, sendedAt, title, coverUrl} = file;
    const date = (new Date(sendedAt)).toLocaleDateString('fr', {
        weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
    });
 
    return (
        <FileWrapper file={file} uris={uris}>
            <BookPlan 
                link={src}
                coverUrl={coverUrl}
                disabledActionButton
                date={date}
                title={title}
            />
        </FileWrapper>
    )
};

export default function BooksContent ({data, uris}) {
    const isSmall = useSelector(state => state.censorshipNavLeft.value.open);

    return (
    <Box
        sx={{display: 'flex', flex: 1}}
    >
        <Box component={Grid} container sx={{my: 1}}>
            {
                data?.map((book, index, videos) => (
                    <Grid 
                        sx={{px:1}} 
                        item 
                        key={index} 
                        xs={isSmall ? 4 : 3}
                    >
                        <BookItem
                            file={book}
                            uris={uris}
                        />
                    </Grid>
                ))
            }
        </Box>
    </Box>
    );
}