import * as React from "react";
import { 
    List, 
    ListItem, 
    ListItemButton, 
    ListItemText, 
    ListSubheader, 
    Box,
    CircularProgress,
    Backdrop
} from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import archiveIconImage from '../../../../icons/icons8-file-64.png';
import medialibraryIconImage from '../../../../icons/icons8-aparat-48.png';
import ImgToIcone from '../../../../icons/ImgToIcon';
import useAxios from "axios-hooks";
import serverPath from "../../../../services/serverPath";
import { Stack } from "@mui/system";
import { addData } from "../../../../redux/apps/censorship/censorshipData";
import getFileExtension from "../../../../services/getFileExtension";
import fileExtensionBase from "../../../../config/fileExtensionBase";
import { setApp } from "../../../../redux/apps/censorship/censorshipNavRight";

const isAuth = (permissions,...apps) => !!apps.find(app => ~permissions?.indexOf(app));

const getNavOption = (permissions) => {
    return (
        [
            {
                label: 'Archives',
                icon: archiveIconImage,
                content: [
                    {
                        label: 'Documents',
                        active: true,
                        id: 'archives/documents',
                    },
                    {
                        label: 'Images',
                        active: true,
                        id: 'archives/images',
                    },
                    {
                        label: 'Vidéos',
                        active: true,
                        id: 'archives/videos',
                    }
                ],
                active: isAuth(permissions, 'archives'),
            }, 
            {

                label: 'Mediathèque',
                icon: medialibraryIconImage,
                content: [
                    {
                        label: 'Bibliothèque',
                        active: isAuth(permissions, 'bibliotheque'),
                        id: 'medialibrary/books',
                    },
                    {
                        label: 'Photothèque',
                        active: isAuth(permissions, 'phototheque'),
                        id: 'medialibrary/photos',
                    },
                    {
                        label: 'Filmothèque',
                        active: isAuth(permissions, 'filmotheque'),
                        id: 'medialibrary/films',
                    }
                ],
                active: isAuth(permissions, 'bibliotheque', 'filmotheque', 'phototheque'),
            }
        ]
    );
}

const keyRefs = {
    'archives/documents': 'archives',
    'archives/images': 'archives',
    'archives/videos': 'archives',
    'medialibrary/books': 'bibliotheque',
    'medialibrary/photos': 'phototheque',
    'medialibrary/films': 'filmotheque',
};

export default function CensorshipNavLeftContent () {
    const permissions = useSelector(state => state.user.value.level.permission);
    const currentData = useSelector(state => state.censorshipData.value);
    const dispatch = useDispatch();
    const token = useSelector(state => state.user.value.token);
    const userId = useSelector(state => state.user.value.id);
    const defaultId = (isAuth(permissions, 'archives') && 'archives/documents') || 
    (isAuth(permissions, 'bibliotheque', 'filmotheque', 'phototheque') && 'medialibrary/books');

    const options = getNavOption(permissions);
    const [{data, loading}, refeth] = useAxios({
        url: URI(JSON.stringify({
            userId,
            where: keyRefs[defaultId],
        })),
        headers: {'Authorization' : `Bearer ${token}`}
    });
    const [currentApp, setCurrentApp] = React.useState(defaultId);

    const handleChangeApp = (app) => {
        setCurrentApp(app.id);
        const params = JSON.stringify({
            userId,
            where: keyRefs[app.id],
        });
        refeth({url: URI(params)});
    };

    React.useEffect(() => {
        const [label, subApp] = defaultId.split('/');
       if(Object.keys(currentData).length === 0)
            dispatch(setApp({app: { label, app: subApp}}));
    }, []);
    
    React.useEffect(() => {
        
        if(!data)
            handleChangeApp({id:defaultId});
       
        if(JSON.stringify(currentData[currentApp]) !== JSON.stringify(data)) 
            if(data) {
                if(!!~currentApp.indexOf('archive')) {
                    const type = currentApp.split('/')[1].slice(0, -1);
                    dispatch(addData({type:currentApp, 
                            value: { 
                                key: currentApp, 
                                data: data?.filter(file => 
                                    fileExtensionBase.find(info =>
                                        ~info.exts.indexOf(getFileExtension(file.fileUrl))
                                        ).type === type
                                        
                                    )
                            } 
                        }));
                }
                else
                    dispatch(addData({type:currentApp, value: { key: currentApp, data} }));
            }

    }, [data]);

    return (
        <React.Fragment>
            <List
            sx={{
                width: '100%',
                position: 'relative',
                overflow: 'auto',
                '& ul': { padding: 0 },
            }}
            subheader={<li />}
            disablePadding
            >
            {options.map((app, index) => app.active &&  (
                <li key={`${index}`}>
                    <ul>
                        <ListSubheader>
                            <Stack
                                direction="row"
                            >
                                    <Box sx={{mr: 2, '& > *':{ position: 'relative', top: 10}}}>
                                        <ImgToIcone
                                            src={app.icon}
                                            size={30}

                                        />  
                                    </Box>
                                    <Box>{app.label}</Box>
                            </Stack>
                        </ListSubheader>
                        {app.content.map((item, index) => item.active && (
                        <ListItem 
                            key={`${index}`} sx={{m:0, p: 0}}
                            selected={item.id === currentApp}
                            onClick={() => {
                                handleChangeApp(item);
                                const [label, subApp] = item.id.split('/');
                                dispatch(setApp({app: { label, app: subApp}}));
                            }}
                        >
                            <ListItemButton>
                                <ListItemText 
                                    primary={`${item.label}`} 
                                    primaryTypographyProps={{
                                        color: 'text.primary'
                                    }}
                                />
                            </ListItemButton>
                        </ListItem>
                        ))}
                    </ul>
                </li>
            ))}
            </List>
            <Backdrop
                sx={{
                    color: '#fff',
                    zIndex: (theme) => theme.zIndex.appBar + 10,
                    backdropFilter: 'blur(15px)',
                }}
                open={!currentData[currentApp] && loading}
            >
                <CircularProgress
                    color="inherit"
                    size="small"
                    sx={{width: 25, height: 25}}
                />
            </Backdrop>
        </React.Fragment>
    );
}

const URI = params => serverPath(`api/stuff/frozen/${params}`);