import * as React from 'react';
import { 
    Box, Button, Card, CardActionArea, CardActions, CardContent, CardHeader, CardMedia, Skeleton, Typography, useTheme, 
} from "@mui/material";
import '../styles/stack-parper.css';
import { ColorExtractor } from "react-color-extractor";
import { Stack } from '@mui/system';
import CropText from './CropText';

function CustomPaper ({coverUrl, src}) {
    const [colors, setColors] = React.useState([])
    const handleGetColors = colors => {
      setColors([...colors]);
    };

    return (
        <Box 
            id="paper"
            sx={{
              '& > .letter': {
                border: theme => `1px solid ${theme.palette.divider}`,
                backgroundColor: /*colors[0] ||*/ 'white',
                boxShadow: 2,
              },
              '& > .letter:before, & > .letter:after': {
                border: theme => `1px solid ${theme.palette.divider}`,
                boxShadow: 2,
                backgroundColor: /*colors[colors.length - 1] ||*/ 'white',
              }
            }}
          >
            <Box
              className="letter"
              sx={{
                '&:hover': {
                  boxShadow: 2,
                  height:130,
                  width:100
                }
              }}
            >
                <ColorExtractor getColors={handleGetColors}>
                  <img
                      src={coverUrl || URI_IMAGE}
                      hidden={!colors.length}
                      height={130}
                      width={100}
                  />
                </ColorExtractor>
                {!colors.length &&
                <Skeleton
                  sx={{
                    width: '100%',
                    height: '100%',
                  }}
                  variant="rectangula"
                />}
              </Box>
          </Box> 
    )
}

export default function StackPaper ({
  name, 
  src, 
  data, 
  disabledActionButton, 
  coverUrl,  
  title, 
  date, 
  link, 
  action,
  description
}) {

  const theme = useTheme();
  return (
    <Card elevation={0} 
            sx={{
                borderRaduis: 5,
                border: theme => `1px solid ${theme.palette.divider}`
            }}
        >
             <CardContent>
                <Stack direction="row">
                    <Box
                      sx={{zIndex: theme => theme.zIndex.drawer + 100}}
                    >
                        <CustomPaper 
                          coverUrl={coverUrl} 
                          src={src}
                        />
                    </Box>
                    <Box>     
                        <CardHeader
                            title={
                                <Typography component="div">
                                    {title.length > 20 ? 
                                        (<CropText
                                            len={16}
                                        >{title}</CropText>)
                                        : title}
                                </Typography>
                            }
                            subheader={
                                <Typography component="div" variant="caption">
                                    {date}
                                </Typography>
                            }
                            sx={{mb:0, pb:0}}
                        />
                        <Typography 
                          variant="body2" 
                          color="text.secondary"
                          sx={{
                            height: 40,
                            mx: 2,
                          }}
                        >{
                          (description.length > 30) ? <CropText len={13}>{description}</CropText> : description
                        }</Typography>
                        {!disabledActionButton &&
                        <CardActions>
                            <Button
                                variant="outlined"
                                size="small"
                                LinkComponent="a"
                                target="_blank"
                                href={link}
                                color={theme.palette.mode === 'dark' ? "inherit" : "primary"}
                            >Lire le document</Button>
                        </CardActions>}
                        {action}
                    </Box>
                </Stack>
             </CardContent>
        </Card>
  )
}
StackPaper.defaultProps = {
  name: '', 
  src: null, 
  data: '', 
  disabledActionButton: false, 
  coverUrl: null,  
  title: '', 
  link: null, 
  action: undefined,
  description: '',
}
const URI_IMAGE = require('../assets/book_cover.png');