import { 
    Alert,
    AlertTitle,
    Box, 
   // Divider, 
    Fade, 
    LinearProgress, 
    Stack, 
    Toolbar, 
    Typography,
} from '@mui/material';
import useAxios from 'axios-hooks';
import propTypes from 'prop-types';
import * as React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import GeidLogo from '../../../components/GeidLogo';
import medialibaryImage from '../../../icons/icons8-aparat-48.png';
import ImgToIcon from '../../../icons/ImgToIcon';
import { openApp, setBookTypes, setData } from '../../../redux/apps/medialibrary/medialibraryNavRight';
import serverPath from '../../../services/serverPath';

export const useGetData = (route, key, loadData) => {
    const localData = useSelector(state => state.medialibraryNavRight.value.data);
    const [{data, error}, refrech, ] = useAxios(URL_MEDIALIBRARY + route, {manual: true});
    const dispacth = useDispatch();
    React.useEffect(() => {
        let timer = null;
        if(loadData) {
            timer = localData[key] ? null : window.setTimeout(() => {
                refrech();
            }, 5000);
    
            if(data) {
                if(JSON.stringify(localData[key]) !== JSON.stringify(data)) 
                    dispacth(setData({[key]: data}));
            } else {
                if(!timer) refrech();
            }
        }
        return () => { 
            if(timer)
                window.clearTimeout(timer);
        }
    }, [data, localData, refrech, dispacth, key, loadData]);

    return [refrech, error];
};

export default function MediaLibraryCover ({loadData}) {
    const medialibraryNavRight = useSelector(state => state.medialibraryNavRight.value);
    const dispacth = useDispatch();
    const [getBooks, getBooksError] = useGetData('/bibliotheque', 'books', loadData);
    const [getImages, getImagesError] = useGetData('/phototheque', 'images', loadData);
    const [getFilms, getFilmsError] = useGetData('/filmotheque', 'films', loadData);
    const [{data:getBookTypes, error:getBookTypesError},] = useAxios(URL_MEDIALIBRARY_BOOKS, {manual: !loadData});
    const [error, setError] = React.useState(null);
   
    const {tab, data:{books, images, films}} = medialibraryNavRight;
    
    const open = !(books && images && films && getBookTypes);

    React.useEffect(() => {
        const refrech =  {
            getBooks,
            getImages,
            getFilms,
        };
        if(loadData && (tab !== 'home')) {
            if(typeof refrech[tab] === 'function') 
                refrech[tab]();
        }
        if(!open) 
            dispacth(openApp());
    }, [tab, open, loadData, dispacth, getBooks, getImages, getFilms]);

    /*Handle the all errors */
    React.useEffect(() => {
        const oneError = [
            getBooksError, 
            getImagesError, 
            getFilmsError, 
            getBookTypesError
        ].find(error => !!error);

        if(oneError && !error) 
            if((oneError.code === 'ERR_NETWORK') && !oneError.response?.data)
                setError({
                    title: 'Promblème de réseau',
                    message: `Impossible d'acceder à la mediathèque, 
                    votre apareil n'est pas connecté sur internet`
                });

    }, [
        getBooksError, 
        getImagesError, 
        getFilmsError, 
        error, 
        getBookTypesError
    ]);
    
    React.useEffect(() => {
        if(getBookTypes) 
                dispacth(setBookTypes({bookTypes: getBookTypes}));
    }, [getBookTypes]);

    return ( open &&
        <Box
            sx={{ 
                zIndex: (theme) => theme.zIndex.drawer + 1,
                bgcolor: 'background.paper',
                hight: '100vh',
                width: '100vw',
                position: 'fixed',
                display: 'flex',
                flex: 1,
                justifyContent: 'center',
                alignItems: 'center',
                top: 0,
                left: 0,
                bottom: 0,
                right: 0
            }}
        >
            <Stack spacing={1}>
                <Toolbar
                    sx={{
                        justifyContent: 'center',
                        alignItems: 'center',
                        display: 'flex',
                    }}
                >
                    {/* <Box>
                        <ImgToIcon
                            src={medialibaryImage}
                            size={50}
                        />
                    </Box>
                    <Divider orientation="vertical" variant="middle" flexItem /> */}
                    <Typography color="text.primary" sx={{mx: 1}} variant="h6">Mediathèque</Typography>
                    {/* <GeidLogo 
                        sx={{ color: 'text.primary' }}
                    /> */}
                </Toolbar>
                <Box sx={{px:3}}>
                    <Fade in={loadData}>
                        {!!error ?
                       ( <Alert
                            severity='error'
                            children={
                                <React.Fragment>
                                    <AlertTitle>{error.title}</AlertTitle>
                                    {error.message}
                                </React.Fragment>
                            }
                        />) :
                        (<LinearProgress
                            color="inherit"
                        />)}
                    </Fade>
                </Box>
                {/* <Alert severity="warning">
                    <Typography 
                        variant="caption" 
                        color="text.secondary"
                    >
                        Cette application est en cours de mise à jour
                    </Typography>
                </Alert> */}
            </Stack>

            <Stack 
                position="absolute"
                bottom={80}
            >
                <Typography 
                    variant="body2" 
                    color="text.secondary"
                >
                    Direction Archives et Nouvelles Technologie de l'Information et de la Communication
                </Typography>
            </Stack>
        </Box>
    );
}

MediaLibraryCover.defaultProps = {
    loadData: false,
};
   

MediaLibraryCover.propTypes = {
    loadData: propTypes.bool,
};

const URL_MEDIALIBRARY = serverPath('/api/stuff');
const URL_MEDIALIBRARY_BOOKS = serverPath('/api/stuff/bibliotheque/types');