import { 
    List, 
    ListItem, 
    ListItemAvatar, 
    ListItemText, 
    Skeleton 
} from "@mui/material";

export default function LoadingList (props) {
    const {nbrList, loading, ...otherProps} = props;
    return ( loading &&
        <List {...otherProps}>
            {
                (() => {
                    let i = 0;
                    const list = [];
                    for(; i < (nbrList || 1); i++)
                        list.push(
                            <ListItem key={i}>
                                <ListItemAvatar>
                                    <Skeleton
                                        variant="circular"
                                        sx={{
                                            width: 50,
                                            height: 50,
                                        }}
                                    />
                                </ListItemAvatar>
                                <ListItemText
                                    primary={
                                        <Skeleton
                                            sx={{flexGrow:1}}
                                        />
                                    }
                                    secondary={
                                        <Skeleton
                                            sx={{flexGrow:1, width: '80%'}}
                                        />
                                    }
                                />
                            </ListItem>
                        )
                    return list;
                })()
            }
        </List>
    );
}