import * as React from 'react';
import {
    Toolbar, 
    Box,
} from '@mui/material';
import MultiLineInput from '../../../component/MultiLineInput';
import SpeedDialOptions from './SpeedDialOptions';
import EmojiNav from './EmojiNav';
import VoiceToSendIcon from './VoiceToSendIcon';
import { useSession } from '../../../../../services/globalConfig';
import WrapperSide from '../../../component/WrapperSide';

export default function SendText ({sender, values, setValues}) {
    const [variant, setVariant] = React.useState('voice');
    const inputRef = React.useRef(null);
    const anchorEl = React.useRef(null);
    const [{socket},] = useSession();
   
    const handleSendMessage = message => {  
       inputRef.current.value = '';
       socket?.emit(`${sender.type || 'direct'}-message`, {
            content: message,
            to: sender._id,
            date: new Date(),
            type: 'text',
       });
    };

    const handleKeyPress = event => {
        const { value } = event.target;
        if (event.key === 'Enter' && event.shiftKey) 
            event.stopPropagation();
        else if (event.key === 'Enter') {
            event.preventDefault();
            if(value?.trim())
                handleSendMessage(value);
       }
    };

    const handleFile = file => {
        setValues({...values, type: 'file', file});
    };

    return (
        <Toolbar>
            <WrapperSide>
                <Box>
                    <EmojiNav
                        values={values}
                        setValues={() => {}}
                        anchorEl={anchorEl.current}
                    />
                </Box>
            </WrapperSide>
            <WrapperSide>
                <Box>
                    <SpeedDialOptions
                        handleFile={handleFile}
                    />
                </Box>
            </WrapperSide>
            <MultiLineInput
                sx={{
                    my: 1,
                    flexGrow: 1,
                }}
                onKeyPress={handleKeyPress}
                onChange={event => {
                    if(event.target.value.trim() && variant === 'voice') 
                        setVariant('send');
                    if(!event.target.value.trim() && variant === 'send')
                        setVariant('voice');
                }}
                ref={inputRef}
            />
           <WrapperSide>
                <VoiceToSendIcon
                    variant={variant}
                    onSendText={() => {
                        const { value } = inputRef.current;
                        if(value.trim()) 
                            handleSendMessage(value);    
                    }}
                />
            </WrapperSide>
        </Toolbar>
    )
}